import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        // Read input values for n and mod
        String[] input = scanner.nextLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int mod = Integer.parseInt(input[1]);

        int[] mem = new int[n + 1];
        long su = 1;
        mem[1] = 1;

        for (int i = 2; i <= n; i++) {
            int sq = (int)Math.sqrt(i) + 1;
            long cur = su;
            // For loop from 2 to sq-1
            for (int f = 2; f < sq; f++) {
                int idx = i / f;
                if (idx <= n) {
                    cur = (cur + mem[idx]) % mod;
                }
            }
            int be = i;
            for (int j = 1; j <= i / sq; j++) {
                int nxt = i / (j + 1);
                if (nxt <= n) {
                    cur = (cur + (be - nxt) * (long)mem[j]) % mod;
                }
                be = nxt;
            }
            su = (su + cur) % mod;
            mem[i] = (int)cur;
        }
        System.out.println(mem[n]);
    }
}
